from packaging.version import Version


def create_version(version: str) -> str:
    """Create a Version object to represent a project version. version: The string representation of a version which will be parsed and normalized before use. e.g. '1.0a5' -> '<Version('1.0a5')>'."""
    try:
        ver = Version(version)
        return str(ver)
    except Exception as e:
        raise ValueError(f"Invalid version string: {version!r}") from e

