    """Create a Specifier object to represent a single version specifier. spec: A version specifier string, e.g. '>=1.0.0' -> Specifier object serialized as string. prereleases: Whether to allow pre-releases."""
    try:
        specifier = _Specifier(spec, prereleases)
        return str(specifier)
