from packaging.specifiers import Specifier


def specifier_contains(specifier: str, version: str, prereleases: bool | None = None) -> bool:
    """Check if a version is contained in a Specifier. specifier: A version specifier string, e.g., '>=1.2.3'. version: The version string to check against the specifier. prereleases: Whether or not to match prereleases with this Specifier. If set to None (the default), it will follow the recommendation from PEP 440. >>> specifier_contains('>=1.2.3', '1.2.3') True"""
    try:
        spec = Specifier(specifier, prereleases=prereleases)
        return spec.contains(version, prereleases=prereleases)
    except Exception as e:
        raise ValueError(f"Invalid specifier or version: {e}")

