from packaging.specifiers import SpecifierSet


def range_contains(version_range: str, version: str, prereleases: bool | None = None, installed: bool | None = None) -> bool:
    """Check if a version is contained in a VersionRange. version_range: A version range specifier compatible with packaging.specifiers.SpecifierSet. version: A version string to check against the range. prereleases: Whether to match pre-releases. None (default) uses the range's own policy. installed: When True, accept a pre-release item even if the range would not otherwise allow it. Example: range_contains(">=1.0,<2.0", "1.5") -> True."""
    try:
        spec_set = SpecifierSet(version_range)
        range_obj = spec_set.to_range()
        return range_obj.contains(version, prereleases, installed)
    except Exception as e:
        raise ValueError(f"Invalid version range or version: {e}")

