def is_version_range_subset(self_range: str, other_range: str) -> bool:
    """Check if one VersionRange is a subset of another. self_range: A version range specifier string for the range to check if it's a subset, other_range: A version range specifier string for the range to check against.

    >>> is_version_range_subset(">=1.5,<1.8", ">=1.0,<2.0")
    True
    """
    try:
        self_ver_range = SpecifierSet(self_range).to_range()
        other_ver_range = SpecifierSet(other_range).to_range()
        return self_ver_range.is_subset(other_ver_range)
    except Exception as e:
        raise ValueError(f"Invalid version range specification: {e}")

