def is_version_range_disjoint(version_range1: str, version_range2: str) -> bool:
    """Check if two version ranges share no members. version_range1: A version range specifier string, e.g. '>=1.0,<2.0'. version_range2: Another version range specifier string, e.g. '>=2.0,<3.0'. Returns True if the ranges are disjoint, False otherwise. >>> is_version_range_disjoint('>=1.0,<2.0', '>=2.0,<3.0') True"""
    try:
        range1 = SpecifierSet(version_range1).to_range()
        range2 = SpecifierSet(version_range2).to_range()
        return range1.is_disjoint(range2)
    except Exception as e:
        raise ValueError(f"invalid version range: {e}")

