def intersection_version_ranges(range1: str, range2: str) -> str:
    """Get the intersection of two version range specifiers. range1: first version range specifier string, range2: second version range specifier string. Example: intersection_version_ranges('>=1.0', '<2.0') -> '>=1.0,<2.0'."""
    try:
        vr1 = SpecifierSet(range1).to_range()
        vr2 = SpecifierSet(range2).to_range()
        result = vr1.intersection(vr2)
        return str(result)
    except Exception as e:
        raise ValueError(f"Invalid version range specification: {e}")

